/* Scoped native component fixture. Versioned execution evidence is separate.
 * Includes the actual preparation helpers and calls the public Core-C refusal
 * boundary. No substitute XFS/project facts, mount operation or positive keeper
 * authorization is supplied. Link with the real Core-C runtime owner.
 * Known SHA oracles below were independently generated with Python hashlib;
 * they are not generated by the implementation under test.
 * A successful component run does NOT qualify full executable preparation. */
#define _GNU_SOURCE
#include "runtime.h"
#include "runtime_workspace_storage_v1.h"
#include <errno.h>
#include <limits.h>
#include <stdint.h>
