static unsigned checks;
#define CHECK(expression) do { checks++; if(!(expression)) { \
    fprintf(stderr,"FAIL:%d:%s\n",__LINE__,#expression); abort(); } } while(0)

static int64_t prep_test_text(const char* text) {
    return rt_string_new((const uint8_t*)text,strlen(text));
}
static int64_t prep_test_now(clockid_t kind) {
    struct timespec value;CHECK(clock_gettime(kind,&value)==0);
    CHECK(value.tv_sec>=0&&(uint64_t)value.tv_sec<((uint64_t)INT64_MAX-60000)/1000);
    return (int64_t)value.tv_sec*1000+value.tv_nsec/1000000;
}
static void prep_test_write(int fd,const void* source,size_t size) {
    const uint8_t* bytes=(const uint8_t*)source;size_t offset=0;
    while(offset<size) {
        ssize_t written=write(fd,bytes+offset,size-offset);
        if(written<0&&errno==EINTR)continue;
        CHECK(written>0);offset+=(size_t)written;
    }
}
static void prep_test_original(int fd) {
    struct stat value;CHECK(fstat(fd,&value)==0);
    CHECK(S_ISREG(value.st_mode));CHECK((value.st_mode&07777)==0600);
    CHECK(value.st_size==3);char bytes[4]={0};
    CHECK(pread(fd,bytes,sizeof(bytes),0)==3);CHECK(memcmp(bytes,"abc",3)==0);
}
static void prep_test_hash(int fd,uint64_t size,const char* expected) {
    char digest[65]={0};struct stat snapshot;
    int64_t mono=prep_test_now(CLOCK_MONOTONIC)+60000;
    int64_t wall=prep_test_now(CLOCK_REALTIME)+60000;
    CHECK(ws_prep_hash_v1(fd,digest,&snapshot,mono,wall)==0);
    CHECK(strcmp(digest,expected)==0);CHECK((uint64_t)snapshot.st_size==size);
    CHECK((snapshot.st_mode&07777)==0600);
}
static void prep_test_paths(void) {
    /* Real mountinfo may include unrelated nsfs roots. They are metadata,
     * never accepted as a selected source or same-device alias path. */
    CHECK(ws_prep_mount_root_v1("mnt:[4026531840]",0));
    CHECK(!ws_prep_mount_root_v1("mnt:[4026531840]",1));
    CHECK(ws_prep_mount_root_v1("/workspace/input",1));
    CHECK(!ws_prep_mount_root_v1("/workspace/../input",1));
    CHECK(!ws_prep_mount_root_v1("",0));
    CHECK(!ws_prep_mount_root_v1("mnt:[4026531840]\n",0));
    CHECK(ws_prep_path_v1("inputs",0));CHECK(ws_prep_path_v1("tools/simple",0));
    CHECK(ws_prep_path_v1("input with spaces",0));CHECK(ws_prep_path_v1("/",1));
    CHECK(!ws_prep_path_v1("/inputs",0));CHECK(!ws_prep_path_v1("inputs",1));
    CHECK(!ws_prep_path_v1("",0));CHECK(!ws_prep_path_v1("../inputs",0));
    CHECK(!ws_prep_path_v1("inputs/../outputs",0));CHECK(!ws_prep_path_v1("./inputs",0));
    CHECK(!ws_prep_path_v1("inputs//tools",0));CHECK(!ws_prep_path_v1("inputs/",0));
    CHECK(!ws_prep_path_v1("inputs\nforged",0));
    CHECK(ws_prep_overlap_v1("/source/input","/source/input"));
    CHECK(ws_prep_overlap_v1("/source","/source/input"));
    CHECK(ws_prep_overlap_v1("/source/input/tools","/source/input"));
    CHECK(!ws_prep_overlap_v1("/source/input","/source/output"));
    CHECK(!ws_prep_overlap_v1("/source/input","/source/input2"));
    char escaped[]="/input\\040with\\040spaces\\134leaf";
    CHECK(ws_prep_unescape_v1(escaped)==0);
    CHECK(strcmp(escaped,"/input with spaces\\leaf")==0);CHECK(ws_prep_path_v1(escaped,1));
    char traversal[]="/safe\\057..\\057escape";
    CHECK(ws_prep_unescape_v1(traversal)==0);CHECK(!ws_prep_path_v1(traversal,1));
    char incomplete[]="/incomplete\\04",nul[]="/nul\\000leaf",newline[]="/line\\012leaf";
    CHECK(ws_prep_unescape_v1(incomplete)==EINVAL);
    CHECK(ws_prep_unescape_v1(nul)==ENOTSUP);CHECK(ws_prep_unescape_v1(newline)==ENOTSUP);
    CHECK(ws_prep_option_v1("rw,nosuid,nodev","rw"));
    CHECK(!ws_prep_option_v1("errors=remount-ro,rw","ro"));
    CHECK(!ws_prep_option_v1("rw,nosuid,nodev","ro"));
}
#endif

int main(void) {
#if defined(__linux__)
    prep_test_paths();
    char directory[]="/tmp/simple-executable-prep-XXXXXX";CHECK(mkdtemp(directory)!=NULL);
    int root=open(directory,O_RDONLY|O_DIRECTORY|O_CLOEXEC|O_NOFOLLOW);CHECK(root>=0);
    int original=openat(root,"producer.exe",O_RDWR|O_CREAT|O_EXCL|O_CLOEXEC|O_NOFOLLOW,0600);CHECK(original>=0);
    prep_test_write(original,"abc",3);prep_test_original(original);
    prep_test_hash(original,3,"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");

    int blob=openat(root,"hash-boundaries",O_RDWR|O_CREAT|O_EXCL|O_CLOEXEC|O_NOFOLLOW,0600);CHECK(blob>=0);
    prep_test_hash(blob,0,"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");
    uint8_t chunk[65536];memset(chunk,'x',sizeof(chunk));
    prep_test_write(blob,chunk,63);
    prep_test_hash(blob,63,"75220b47218278e656f2013bb8f0c455a25eaf01e86c64924e9d48d89776d6f2");
    CHECK(ftruncate(blob,0)==0);CHECK(lseek(blob,0,SEEK_SET)==0);
    prep_test_write(blob,chunk,sizeof(chunk));
    prep_test_hash(blob,65536,"1f8745f0d2d1387ec1af2211a3cf417b2e9e885e853472649c1d979d0e9370e3");
    prep_test_write(blob,"x",1);
    prep_test_hash(blob,65537,"1abe08ebecf1c18cab71f6fe28aaddf20268f85bad78bb9a72f88ca47c874662");
    CHECK(ftruncate(blob,(off_t)WS_PREP_FILE_BYTES_V1+1)==0);
    char digest[65]={0};struct stat snapshot;
    CHECK(ws_prep_hash_v1(blob,digest,&snapshot,prep_test_now(CLOCK_MONOTONIC)+60000,
        prep_test_now(CLOCK_REALTIME)+60000)==EFBIG);
    CHECK(digest[0]==0); /* Size refusal occurs before reading/hashing. */

    int64_t mono=prep_test_now(CLOCK_MONOTONIC),wall=prep_test_now(CLOCK_REALTIME);
    CHECK(ws_prep_deadline_v1(0,wall+60000,1)==EINVAL);
    CHECK(ws_prep_deadline_v1(mono+60000,0,1)==EINVAL);
    CHECK(ws_prep_deadline_v1(mono,wall+60000,1)==ETIMEDOUT);
    CHECK(ws_prep_deadline_v1(mono+60000,wall,1)==ETIMEDOUT);
    CHECK(ws_prep_hash_v1(original,digest,&snapshot,mono,wall+60000)==ETIMEDOUT);
    prep_test_original(original);
    WsExecutablePrepFactsV1 facts;memset(&facts,0xff,sizeof(facts));
    CHECK(ws_prepare_executable_v1(NULL,NULL,"inputs","outputs","producer.exe",
        "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
        mono+60000,wall+60000,&facts)==EINVAL);
    CHECK(facts.state==0&&facts.error==EINVAL);CHECK(facts.file_identity[0]==0);
    prep_test_original(original);

    const char* pin="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
    int64_t mapping=prep_test_text(pin),stage=prep_test_text(pin);
    int64_t input=prep_test_text("inputs"),output=prep_test_text("outputs");
    int64_t executable=prep_test_text("producer.exe"),expected=prep_test_text(
        "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");
    CHECK(rt_string_len(rt_workspace_storage_prepare_executable_v1(-1,-1,mapping,stage,
        wall+60000,input,output,executable,expected))==0);
    CHECK(rt_string_len(rt_workspace_storage_prepare_executable_v1(0,0,mapping,stage,
        wall+60000,input,output,executable,expected))==0);
    CHECK(rt_string_len(rt_workspace_storage_prepare_executable_v1(-1,-1,prep_test_text("invalid"),stage,
        wall+60000,input,output,executable,expected))==0);
    prep_test_original(original);

    /* Even an effective-root harness may not credit capability traversal of a
     * directory without the target owner's execute bit. Restore only our own
     * fixture directory; production code never performs this restoration. */
    CHECK(ws_prep_traverse_v1(root)==0);CHECK(fchmod(root,0600)==0);
    CHECK(ws_prep_traverse_v1(root)==EACCES);CHECK(fchmod(root,0700)==0);
    CHECK(ws_prep_traverse_v1(root)==0);

    int observer=open("/proc/thread-self",O_RDONLY|O_DIRECTORY|O_CLOEXEC);CHECK(observer>=0);
    WsPrepMountsV1* mounts=calloc(1,sizeof(*mounts));CHECK(mounts!=NULL);mounts->namespace_fd=-1;
    int mount_error=ws_prep_mount_read_v1(observer,mounts,1);
    if(!mount_error) {
        CHECK(mounts->count>0&&mounts->count<=WS_PREP_MOUNT_ROWS_V1);
        CHECK(strlen(mounts->raw)<=WS_PREP_MOUNT_BYTES_V1);CHECK(mounts->namespace_fd>=0);
        struct stat namespace_stat;CHECK(fstat(mounts->namespace_fd,&namespace_stat)==0);
        CHECK((uint64_t)namespace_stat.st_dev==mounts->namespace_device);
        CHECK((uint64_t)namespace_stat.st_ino==mounts->namespace_inode);
        uint64_t mount_id=0;mount_error=ws_prep_mount_id_v1(root,&mount_id);
        if(!mount_error) {
            CHECK(mount_id>0);
            WsPrepMountRowV1* row=ws_prep_mount_find_v1(mounts,mount_id);CHECK(row!=NULL);
            struct stat root_stat;CHECK(fstat(root,&root_stat)==0);
            CHECK(row->major_id==major(root_stat.st_dev)&&row->minor_id==minor(root_stat.st_dev));
            CHECK(ws_prep_path_v1(row->root,1)&&ws_prep_path_v1(row->point,1));
        }
    }
    if(mounts->namespace_fd>=0)CHECK(close(mounts->namespace_fd)==0);
    free(mounts);CHECK(close(observer)==0);
    prep_test_original(original);CHECK(close(original)==0);CHECK(close(blob)==0);
    CHECK(unlinkat(root,"producer.exe",0)==0);CHECK(unlinkat(root,"hash-boundaries",0)==0);
    CHECK(close(root)==0);CHECK(rmdir(directory)==0);
    if(mount_error) {
        fprintf(stderr,"BLOCKED native mount-observation fixture: errno=%d; no fixture PASS\n",mount_error);
        return 77;
    }
    printf("PASS scoped executable-preparation components: %u dynamic checks; hashes, bounds, deadlines, refusal, real mount observation\n",checks);
    puts("BLOCKED full positive preparation: requires admitted keeper authority, actual XFS project quota and verified RO/RW guest mounts; no chmod success qualified");
    return 0;
#else
    fputs("UNSUPPORTED: Linux executable-preparation component fixture requires Linux; no PASS\n",stderr);
    return 77;
#endif
}
